function u_s_out = mfun_cvc_current_controller(i_s_ref_in, fbk_in, u_c_lim_ab_in, enable, p)
%MFUN_CVC_CURRENT_CONTROLLER Block CurrentController of the control system.
%   CurrentController of motulator. Generated by motulator_export from the MATLAB port
%   of motulator and called by the MATLAB Function block of the library of motulator,
%   whose folder motulator.setup adds to the MATLAB path. The parameters are the fields
%   of the struct p (from the mask, [] as NaN). The state is in persistent variables, of
%   which each MATLAB Function block has its own copy. The inputs without direct
%   feedthrough come through unit delays, so the update of the state with them is done
%   at the next call.
persistent self pending
if isempty(self)
    % Machine model (InductionMachineInvGammaPars)
    par = struct('n_p', p.par_n_p, 'R_s', p.par_R_s, 'R_R', p.par_R_R, ...
        'L_sgm', p.par_L_sgm, 'L_M', p.par_L_M);
    self = im_current_ctrl_init(par, p.alpha_c, p.alpha_i, p.discrete, p.T_s);
    % Feedback signals of the sampling period, for its update done at the next call
    self.fbk_u_s = complex(0);
    self.fbk_w_c = 0;
    self.fbk_theta_c = 0;
    pending = false;
end
% Update of the previous sampling period with its inputs (the inputs
% u_c_lim_ab, enable through unit delays)
if pending
    u_c_lim_ab = complex_in(u_c_lim_ab_in);
    % The discrete-time controller takes its limited output, except with blocked
    % gates, when the open-circuit voltage of the observer is the realized one
    u = self.fbk_u_s;
    if self.discrete && enable > 0
        u = exp(-1i*self.fbk_theta_c)*u_c_lim_ab;
    end
    self = im_current_ctrl_update(self, p.T_s, u, self.fbk_w_c);
end
pending = true;
i_s_ref = complex_in(i_s_ref_in);
fbk = im_observer_outputs_unpack(fbk_in);
[self, u_s] = im_current_ctrl_compute_output(self, i_s_ref, fbk.i_s);
self.fbk_u_s = fbk.u_s;
self.fbk_w_c = fbk.w_c;
self.fbk_theta_c = fbk.theta_c;
u_s_out = complex_out(u_s);
end

function s = im_observer_outputs_unpack(u)
%IM_OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'psi_R', complex(u(9), u(10)), ...
    'tau_M', u(11), ...
    'w_c', u(12), ...
    'w_s', u(13), ...
    'w_r', u(14), ...
    'w_m', u(15), ...
    'w_M', u(16), ...
    'theta_c', u(17), ...
    'e_o', complex(u(18), u(19)), ...
    'eps', u(20), ...
    'h', u(21));
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function self = complex_pi_init(k_p, k_i, k_t)
%COMPLEX_PI_INIT 2DOF synchronous-frame complex-vector PI controller
%   (ComplexPIController).
self = struct('k_p', k_p, 'k_t', k_t, 'alpha_i', k_i/k_t, 'u_i', complex(0), ...
    'v', complex(0));
end

function [self, u] = complex_pi_compute_output(self, i_ref, i, u_ff)
%COMPLEX_PI_COMPUTE_OUTPUT Controller output.
% Disturbance input estimate
self.v = self.u_i - (self.k_p - self.k_t)*i + u_ff;
u = self.k_t*(i_ref - i) + self.v;
end

function self = complex_pi_update(self, T_s, u, w_c)
%COMPLEX_PI_UPDATE Update the integral state with the realized output u.
self.u_i = self.u_i + T_s*(self.alpha_i + 1i*w_c)*(u - self.v);
end

function self = discrete_complex_init(alpha_c, T_s)
%DISCRETE_COMPLEX_INIT Direct discrete-time 2DOF complex-vector controller
%   (DiscreteComplexController), whose design includes the computational delay, so
%   that the angle of the output is not advanced (k_comp = 0 in the control system).
self = struct('T_s', T_s, 'beta', exp(-alpha_c*T_s), 'u_i', complex(0), ...
    'u_lim', complex(0), 'w_c', 0, 'e', complex(0), 'u', complex(0));
end

function k = discrete_complex_gains(self, w_c)
%DISCRETE_COMPLEX_GAINS Gains [k_t k_i k_1 k_2] of the complex-vector design
%   (_gains).
T_s = self.T_s;
beta = self.beta;
Phi = exp(-1i*w_c*T_s); % Rotation of the coordinates over T_s
Phi2 = Phi*Phi;
k = [(1 - beta)/(Phi2*T_s), (1 - beta)*(1 - beta*Phi)/(Phi2*T_s*T_s), ...
    (1 - beta)*(1 + (1 - beta)/Phi + 1/Phi2)/T_s, (1 - beta)*(1 + Phi)];
end

function [self, u] = discrete_complex_compute_output(self, i_ref, i)
%DISCRETE_COMPLEX_COMPUTE_OUTPUT Controller output.
k = discrete_complex_gains(self, self.w_c);
self.e = i_ref - i;
self.u = k(1)*i_ref - k(3)*i - k(4)*self.u_lim + self.u_i;
u = self.u;
end

function self = discrete_complex_update(self, T_s, u, w_c)
%DISCRETE_COMPLEX_UPDATE Update with the limited output u and the angular speed w_c
%   of the coordinates.
k = discrete_complex_gains(self, self.w_c);
self.u_i = self.u_i + T_s*k(2)*(self.e - (self.u - u)/k(1));
self.u_lim = complex(u);
self.w_c = w_c;
end

function self = im_current_ctrl_init(par, alpha_c, alpha_i, discrete, T_s)
%IM_CURRENT_CTRL_INIT Current controller: a 2DOF PI controller with the gains from
%   the bandwidths and the leakage inductance (CurrentController) or, if discrete is
%   true, the direct discrete-time controller of the leakage flux linkages L_sgm*i
%   (DiscreteCurrentController).
k_t = alpha_c*par.L_sgm;
k_i = alpha_c*alpha_i*par.L_sgm;
k_p = (alpha_c + alpha_i)*par.L_sgm;
self = struct('L_sgm', par.L_sgm, 'discrete', logical(discrete), ...
    'pi', complex_pi_init(k_p, k_i, k_t), 'dc', discrete_complex_init(alpha_c, T_s));
end

function [self, u] = im_current_ctrl_compute_output(self, i_ref, i)
%IM_CURRENT_CTRL_COMPUTE_OUTPUT Voltage reference.
if self.discrete
    % The currents mapped to the leakage flux linkages
    [self.dc, u] = discrete_complex_compute_output(self.dc, self.L_sgm*i_ref, ...
        self.L_sgm*i);
else
    [self.pi, u] = complex_pi_compute_output(self.pi, i_ref, i, 0);
end
end

function self = im_current_ctrl_update(self, T_s, u, w_c)
%IM_CURRENT_CTRL_UPDATE Update the states with the realized voltage u, or with the
%   limited voltage reference of the discrete-time controller.
if self.discrete
    self.dc = discrete_complex_update(self.dc, T_s, u, w_c);
else
    self.pi = complex_pi_update(self.pi, T_s, u, w_c);
end
end
